public int divisibleSumPairs(int n, int k, List<Integer> ar) {
    int[] count = new int[k];
    int pairs = 0;
    for (int x : ar) {
        int r = x % k;
        int complement = (k - r) % k;
        pairs += count[complement];
        count[r]++;
    }
    return pairs;
}
